package dev.eugheist.ttmodern;
final class AwakenedShovelAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT awakened shovel: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var p=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"PickAudit"));p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);var stack=new net.minecraft.world.item.ItemStack(AwakenedShovel.ITEM.get());p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,stack);var origin=new net.minecraft.core.BlockPos(5,290,5);p.setPos(5.5,292,5.5);p.setXRot(90);p.setYRot(0);var positions=new java.util.HashSet<>(AdvancedToolModes.shovel(1,net.minecraft.core.Direction.UP).positions(origin));positions.addAll(AdvancedToolModes.shovel(2,net.minecraft.core.Direction.UP).positions(origin));positions.add(origin);var saved=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();positions.forEach(at->saved.put(at,level.getBlockState(at)));
 try{for(int mode=0;mode<3;mode++){positions.forEach(at->level.setBlock(at,net.minecraft.world.level.block.Blocks.DIRT.defaultBlockState(),2));check(p.gameMode.destroyBlock(origin),"real center break "+mode);long count=positions.stream().filter(at->level.getBlockState(at).isAir()).count();check(count==new int[]{1,25,16}[mode],"native selected mode exact break count "+mode+"="+count);p.setShiftKeyDown(true);AwakenedShovel.ITEM.get().use(level,p,net.minecraft.world.InteractionHand.MAIN_HAND);p.setShiftKeyDown(false);check(AdvancedToolModes.get(stack)==(mode+1)%3,"native shift-use cycles mode");}
 level.setBlock(origin,net.minecraft.world.level.block.Blocks.GRASS_BLOCK.defaultBlockState(),2);level.setBlock(origin.above(),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),2);var context=new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(origin),net.minecraft.core.Direction.UP,origin,false));for(var shovel:java.util.List.of(AwakenedShovel.ITEM.get(),KamiTools.SHOVEL.get())){p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(shovel));check(shovel.useOn(context)==net.minecraft.world.InteractionResult.PASS&&level.getBlockState(origin).is(net.minecraft.world.level.block.Blocks.GRASS_BLOCK),"no invented modern grass path action");}level.setBlock(origin,net.minecraft.world.level.block.Blocks.OAK_LOG.defaultBlockState(),2);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(KamiTools.AXE.get()));check(KamiTools.AXE.get().useOn(context)==net.minecraft.world.InteractionResult.PASS&&level.getBlockState(origin).is(net.minecraft.world.level.block.Blocks.OAK_LOG),"no invented modern stripping action");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,stack);
 var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("ICHOR_SHOVEL_GEM")).findFirst().orElseThrow();var parts=recipe.componentStacks();check(parts.size()==12&&parts.stream().noneMatch(net.minecraft.world.item.ItemStack::isEmpty)&&parts.get(2).is(FocusResearch.item("elemental_shovel"))&&parts.get(10).is(FocusResearch.item("elemental_shovel"))&&parts.get(5).is(FocusResearch.item("cinnabar_cluster")),"original resolved twelve components");check(dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,new net.minecraft.world.item.ItemStack(KamiTools.SHOVEL.get()),java.util.Set.of("ICHOR_SHOVEL_GEM"))==recipe,"native infusion accepted");check(recipe.instability()==15&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.MINE)==64&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.EARTH)==82,"original costs");System.out.println("TT AWAKENED SHOVEL AUDIT: ALL PASS (real native single/25block/column16 mining,shift-use cycle,12part infusion/research,costs)");
 }finally{saved.forEach((at,state)->level.setBlock(at,state,2));p.discard();}
 }
}
